//! Types generated by `ibis_part!` from the test file
//! `crates/kicad_lib/tests/fixtures/models/ibis_part.ibs`: their functions return what the run-time
//! API returns for the same pins.

use cuprite_wire::{
    ibis::Corner,
    ibis_part,
    spice::ibis::{IbisBuffer, IbisDiffBuffer, IbisSeries, read_file},
};

ibis_part! {
    /// The test chip.
    pub struct Chip {
        library: "crates/kicad_lib/tests/fixtures/models/ibis_part.ibs",
        component: "Chip",
        pins: {
            tx => "3",
            io_in => { pin: "4", model: "in_cmos" },
            io => { pin: "4" },
        },
        diff_pins: { rx => "2" },
        series: { term => ["7", "8"] },
    }
}

ibis_part! {
    /// The only pin of the other component; the file has two, so it is named.
    struct Other {
        library: "crates/kicad_lib/tests/fixtures/models/ibis_part.ibs",
        component: "Other",
        pins: { a => "1" },
    }
}

const PATH: &str = concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/crates/kicad_lib/tests/fixtures/models/ibis_part.ibs"
);

#[test]
fn test_constants() {
    assert_eq!(Chip::LIBRARY, PATH);
    assert_eq!(Chip::COMPONENT, "Chip");
    assert_eq!(Other::COMPONENT, "Other");
    // Read once.
    assert!(std::ptr::eq(Chip::file().unwrap(), Chip::file().unwrap()));
}

#[test]
fn test_functions_match_the_run_time_api() {
    let file = read_file(PATH).unwrap();
    for corner in [Corner::Typ, Corner::Min, Corner::Max] {
        assert_eq!(
            Chip::tx(corner).unwrap(),
            IbisBuffer::of_pin(&file, "Chip", "3", corner).unwrap()
        );
        assert_eq!(
            Chip::io_in(corner).unwrap(),
            IbisBuffer::of_pin_model(&file, "Chip", "4", "in_cmos", corner).unwrap()
        );
        assert_eq!(
            Chip::rx(corner).unwrap(),
            IbisDiffBuffer::of_pin(&file, "Chip", "1", corner).unwrap()
        );
        assert_eq!(
            Chip::term(corner).unwrap(),
            IbisSeries::of_pins(&file, "Chip", "7", "8", corner).unwrap()
        );
        assert_eq!(
            Other::a(corner).unwrap(),
            IbisBuffer::of_pin(&file, "Other", "1", corner).unwrap()
        );
    }
    assert_eq!(Chip::io_in(Corner::Typ).unwrap().model_name(), "in_cmos");
    // The default of the selector is its first model.
    assert_eq!(Chip::io(Corner::Typ).unwrap().model_name(), "out_3s");
    assert_eq!(
        Chip::rx(Corner::Typ)
            .unwrap()
            .termination()
            .unwrap()
            .model_name(),
        "term"
    );
}
